// PIPEDRIVE REFERRAL NETWORK — CONFIG
// Everything you might want to change lives in this one node. Nothing else in either
// workflow needs editing.
//
// The same config node ships in BOTH workflows and is generated from one file, so the
// activity guard and the reporting run can never disagree about a stage name.
//
// Any key left blank means that step is SKIPPED, not that the run fails. That is what lets
// this be demonstrated on a screen-share before a single credential exists.

// ---------------------------------------------------------------- Your Pipedrive account
// COMPANY_DOMAIN is the first part of your Pipedrive web address:
//   https://<THIS BIT>.pipedrive.com
// API_TOKEN is Settings -> Personal preferences -> API. Blank = nothing is read or written
// and the run falls back to the built-in demo pipeline (see DEMO_PIPELINE).
const COMPANY_DOMAIN = '';
const API_TOKEN      = '';

// The pipeline this runs against. Leave PIPELINE_ID blank to work every open deal in the
// account; set it once you have more than one pipeline.
const PIPELINE_ID = '';

// Every read is paginated (500 per page, Pipedrive's maximum). MAX_PAGES is a safety stop:
// 20 pages = 10,000 open deals. If a read is cut off by it, the run is reported as a FAILED
// read, never as a smaller pipeline — a half-read pipeline reads as "covered" by omission.
const MAX_PAGES = 20;

// ---------------------------------------------------------------- The pipeline's stages
// In order. `id` is Pipedrive's numeric stage id — read it off the URL when you open the
// stage's settings. The rest is this workflow's rule for that stage.
//
//   next_type    the activity type key created when a deal in this stage has no next step
//   due_in_days  how far ahead that activity is scheduled
//   subject      what the activity is called, so a rep reads it and knows what to do
//   stale_days   no activity of ANY kind for this long -> the deal is reported as stalling
//
// A stage with next_type '' is one where the guard deliberately does nothing.
const STAGES = [
  { id: 1, name: 'Target Identified',      next_type: 'initial_call',
    due_in_days: 1,  stale_days: 14,
    subject: 'First outreach call — introduce Trialbridge and the referral network' },
  { id: 2, name: 'Outreach Started',       next_type: 'follow_up_call',
    due_in_days: 3,  stale_days: 10,
    subject: 'Follow-up call — no answer yet on the first attempt' },
  { id: 3, name: 'Contact Made',           next_type: 'follow_up_call',
    due_in_days: 5,  stale_days: 14,
    subject: 'Follow up — find the decision maker for referrals' },
  { id: 4, name: 'Decision Maker Engaged', next_type: 'physician_meeting',
    due_in_days: 7,  stale_days: 14,
    subject: 'Book the physician meeting' },
  { id: 5, name: 'Meeting Scheduled',      next_type: 'materials_drop_off',
    due_in_days: 2,  stale_days: 21,
    subject: 'Confirm the meeting and drop off study materials' },
  { id: 6, name: 'Interested / Follow-Up', next_type: 'referral_follow_up',
    due_in_days: 7,  stale_days: 21,
    subject: 'Follow up with an interested practice — do not let this go quiet' },
  { id: 7, name: 'Referral Partner',       next_type: 'thank_you_call',
    due_in_days: 3,  stale_days: 30,
    subject: 'Thank-you call — confirm the referral process is working for them' },
  { id: 8, name: 'Actively Referring',     next_type: 'referral_follow_up',
    due_in_days: 30, stale_days: 45,
    subject: 'Monthly referral partner check-in' }
];

// A referral partner with no activity of any kind for this long gets a re-engagement
// activity instead of the routine check-in. This is the "inactive referral partner"
// automation.
//
// It is measured on activity, not on referrals, because referral counts only exist once
// RESULT_FIELDS are wired up and this has to work on day one. Once they are wired, the
// weekly report's "Last referral" column is the sharper signal — read both.
const REENGAGE_AFTER_DAYS = 60;
const REENGAGE_TYPE       = 're_engagement';
const REENGAGE_SUBJECT    = 'Re-engagement — no referrals from this practice recently';

// Activity type keys, exactly as they appear in Pipedrive (Settings -> Activity types ->
// each type has a key, not the label). The guard creates activities of these types only.
const ACTIVITY_TYPES = {
  initial_call:       'initial_call',
  follow_up_call:     'follow_up_call',
  email:              'email',
  office_visit:       'office_visit',
  materials_drop_off: 'materials_drop_off',
  physician_meeting:  'physician_meeting',
  practice_manager:   'practice_manager_meeting',
  lunch_meeting:      'lunch_meeting',
  referral_follow_up: 'referral_follow_up',
  thank_you_call:     'thank_you_call',
  re_engagement:      're_engagement'
};

// ---------------------------------------------------------------- The rule
// NO OPEN OPPORTUNITY SHOULD EXIST WITHOUT A NEXT ACTIVITY.
//
// A deal counts as covered when it has at least one activity that is not done and is due
// no later than HORIZON_DAYS from now. An activity scheduled eleven months out is not a
// next step, it is a way of passing the check.
const HORIZON_DAYS = 45;

// A deal created in the last GRACE_HOURS is left alone — the rep is probably still typing.
const GRACE_HOURS = 4;

// Hard ceiling on activities created per run. A misconfigured stage list should cost you
// forty stray activities, not two thousand.
const DAILY_CAP = 40;

// ---------------------------------------------------------------- Business days
// Every "days" setting in this node is counted in BUSINESS days: due dates never land on a
// weekend or a holiday, and a task due on Friday is not "3 days overdue" on Monday morning.
// WORK_DAYS uses 0 = Sunday ... 6 = Saturday. HOLIDAYS are 'YYYY-MM-DD' strings.
const WORK_DAYS = [1, 2, 3, 4, 5];
const HOLIDAYS  = [];

// ---------------------------------------------------------------- Escalation tiers
// A deal whose next activity is overdue does NOT get another one stacked on top of it.
// Stacking is how a rep ends up with 60 open tasks and stops reading any of them. Instead:
//
//   overdue OVERDUE_DAYS or more        -> tier "owner":   the rep's own morning DM
//   overdue MANAGER_AFTER_DAYS or more  -> tier "manager": the management escalation
//
// The manager is told about a deal ONCE, then again only if it is still open after
// REMIND_MANAGER_AFTER_DAYS — a daily repeat of the same twelve deals is how an escalation
// channel gets muted. Memory lives in the workflow's own static data; nothing to set up.
const OVERDUE_DAYS              = 3;
const MANAGER_AFTER_DAYS        = 7;
const REMIND_MANAGER_AFTER_DAYS = 5;

// ---------------------------------------------------------------- Rep workload
// New activities are load-levelled: if a rep already has MAX_PER_OWNER_PER_DAY open
// activities due on the target day, the new one moves to the next business day with room,
// up to LEVEL_WITHIN_DAYS later. Forty tasks dumped on one Monday get done on none of them.
const MAX_PER_OWNER_PER_DAY = 8;
const LEVEL_WITHIN_DAYS     = 3;

// Deals worth more than this that have gone stale are called out separately, which is the
// "management notification for high-priority opportunities" automation.
const HIGH_PRIORITY_VALUE = 25000;

// ---------------------------------------------------------------- The PHI boundary
// Pipedrive is Trialbridge's physician/practice business-development CRM. It is NOT the
// patient clinical database. Patient screening and clinical information live elsewhere.
//
// This workflow refuses to read or write any field whose name contains one of these words.
// It is a hard stop, not a warning: the run fails loudly rather than quietly moving a
// diagnosis into a CRM that was never scoped to hold one.
const FORBIDDEN_FIELD_WORDS = [
  'diagnosis', 'diagnoses', 'medication', 'prescription', 'symptom', 'medical record',
  'mrn', 'chart number', 'date of birth', 'dob', 'ssn', 'social security', 'insurance id',
  'member id', 'screening response', 'screening answer', 'eligibility answer', 'lab result',
  'patient name', 'patient email', 'patient phone', 'patient address', 'phi'
];

// Aggregate recruitment results ARE in scope — counts, never people. These are Pipedrive
// deal custom-field keys (Settings -> Data fields -> the 40-character key).
// Blank means that number is not tracked yet and is reported as "not captured" rather than
// silently as a zero.
const RESULT_FIELDS = {
  referrals_sent:      '',   // patient referrals from this practice
  prescreen_qualified: '',   // referrals that passed pre-screen
  sent_to_site:        '',   // patients sent on to a research site
  screened:            '',   // patients screened at the site
  randomized:          ''    // patients randomised / enrolled
};

// Deal custom fields the guard is allowed to read for context. Same key format.
const CONTEXT_FIELDS = {
  specialty:     '',
  territory:     '',
  study_code:    '',
  practice_size: ''
};

// ---------------------------------------------------------------- Reporting (workflow 02)
// The management dashboard. Pipedrive Insights covers the single-object counts; this covers
// the funnel that spans deals, activities and aggregate results, which Insights cannot.
// Blank sheet id = the numbers are computed and posted to chat, but nothing is written down.
const SHEET_ID        = '';
const DASHBOARD_TAB   = 'Dashboard';    // one row per run, so the trend is the sheet history
const GAPS_TAB        = 'Gaps';         // active deals with no future activity, one row each
const BY_REP_TAB      = 'By rep';       // results by marketing representative
const BY_PRACTICE_TAB = 'By practice';  // results by physician / practice

const DASHBOARD_COLUMNS = {
  run_at:              'Run at',
  open_deals:          'Open deals',
  covered:             'With a next activity',
  gaps:                'Without a next activity',
  coverage_pct:        'Coverage %',
  overdue:             'Overdue activities',
  outreach_attempts:   'Outreach attempts',
  conversations:       'Meaningful conversations',
  meetings:            'Meetings',
  new_partners:        'New referral partners',
  active_partners:     'Actively referring practices',
  referrals_sent:      'Patient referrals',
  prescreen_qualified: 'Pre-screen qualified',
  sent_to_site:        'Sent to site',
  screened:            'Screened',
  randomized:          'Randomised / enrolled',
  referral_to_screen:  'Referral to screen %',
  screen_to_random:    'Screen to randomised %',
  stalled:             'Stalled deals',
  high_priority:       'High-priority stalled'
};

const GAP_COLUMNS = {
  deal_id:       'Deal id',
  deal:          'Deal',
  organisation:  'Practice',
  person:        'Physician / contact',
  stage:         'Stage',
  owner:         'Rep',
  value:         'Value',
  last_activity: 'Last activity',
  days_quiet:    'Days quiet',
  action:        'What the guard did',
  run_at:        'Run at'
};

const BY_REP_COLUMNS = {
  rep:               'Rep',
  open_deals:        'Open deals',
  gaps:              'Without a next activity',
  overdue:           'Overdue activities',
  outreach_attempts: 'Outreach attempts',
  conversations:     'Meaningful conversations',
  meetings:          'Meetings',
  new_partners:      'New referral partners',
  referrals_sent:    'Patient referrals',
  run_at:            'Run at'
};

const BY_PRACTICE_COLUMNS = {
  organisation:        'Practice',
  stage:               'Stage',
  owner:               'Rep',
  referrals_sent:      'Patient referrals',
  prescreen_qualified: 'Pre-screen qualified',
  sent_to_site:        'Sent to site',
  screened:            'Screened',
  randomized:          'Randomised / enrolled',
  last_referral:       'Last referral',
  run_at:              'Run at'
};

// Which activity types count as which KPI. An "outreach attempt" is any attempt; a
// "meaningful conversation" is one that was marked done with an outcome that was not a
// no-answer. The distinction is the whole point of the dashboard — attempts are effort,
// conversations are progress.
const OUTREACH_TYPES     = ['initial_call', 'follow_up_call', 'email', 'office_visit',
                            'materials_drop_off', 're_engagement'];
const CONVERSATION_TYPES = ['initial_call', 'follow_up_call', 'referral_follow_up',
                            'thank_you_call', 'practice_manager_meeting'];
const MEETING_TYPES      = ['physician_meeting', 'practice_manager_meeting', 'lunch_meeting',
                            'office_visit'];

// Activity notes that mean "nobody was reached", so the attempt is not counted as a
// conversation. Matched case-insensitively against the note and the subject.
const NO_ANSWER_WORDS = ['no answer', 'voicemail', 'left message', 'left a message',
                         'gatekeeper', 'not available', 'call back later', 'busy signal'];

// Stages that mean the practice is a partner, for the "new referral partners" count.
const PARTNER_STAGES = ['Referral Partner', 'Actively Referring'];

const REPORT_WINDOW_DAYS = 7;   // the reporting period. 7 = the weekly management report.

// Week-over-week: the report compares itself with the newest Dashboard row that is at least
// BASELINE_MIN_DAYS old, read back from the sheet. No sheet = no comparison, said so.
const BASELINE_MIN_DAYS = 5;

// Rep coaching flags in the weekly report. A rep is flagged when:
//   - COACH_MIN_ATTEMPTS+ attempts but under COACH_MIN_CONVERSATION_PCT% became
//     conversations (effort without progress — a list or a script problem), or
//   - over COACH_MAX_GAP_PCT% of their open deals have no next activity (follow-up slipping).
const COACH_MIN_ATTEMPTS         = 6;
const COACH_MIN_CONVERSATION_PCT = 40;
const COACH_MAX_GAP_PCT          = 30;

// ---------------------------------------------------------------- Notifications
const ALERT_WEBHOOK_URL   = '';   // Slack incoming webhook, the team run summary. Also
                                  // where a FAILED Pipedrive read is reported.
const MANAGER_WEBHOOK_URL = '';   // Optional second webhook for management escalations.
                                  // Blank = escalations go to ALERT_WEBHOOK_URL instead.

// Per-rep morning DMs in Slack: each owner gets only their own deals — what was scheduled
// for them, what they are overdue on. Needs a Slack credential on "[cred] Slack - DM each
// owner" (bot scope chat:write), SLACK_DMS = true, and the map below.
// OWNER_SLACK_IDS maps a Pipedrive user id to a Slack member id: { 11: 'U01ABCDEF' }.
// Reps not in the map are simply not DM'd — they are still in the team summary.
const SLACK_DMS       = false;
const OWNER_SLACK_IDS = {};

// ---------------------------------------------------------------- Demo mode
// With no API token set, builds a deterministic fake pipeline — eight stages, twenty-odd
// deals, a realistic spread of covered, uncovered, overdue and stalled — so the whole rule
// can be watched end to end before an account exists. While this is on the run is FORCED
// into preview: a fabricated deal can never produce a real Pipedrive write.
const DEMO_PIPELINE = true;

// ---------------------------------------------------------------- Safety switch
//   TEST_RUN true,  TEST_OWNER_ID blank -> PREVIEW. Every activity the guard would create
//                                          is listed with its deal, stage and due date, and
//                                          nothing is written to Pipedrive. Ships this way.
//   TEST_RUN true,  TEST_OWNER_ID set   -> TEST. Activities really are created, but all
//                                          assigned to that one user, so a real rep's task
//                                          list is not touched while you are testing.
//   TEST_RUN false                      -> LIVE. Activities are created and assigned to the
//                                          deal's own owner.
const TEST_RUN      = true;
const TEST_OWNER_ID = '';

const DEMO_DATA = DEMO_PIPELINE === true && API_TOKEN.trim() === '';

let MODE = TEST_RUN !== true ? 'live'
  : (String(TEST_OWNER_ID).trim() !== '' ? 'test' : 'preview');

// Demo deals are not evidence. They cannot open the write gate, whatever TEST_RUN says.
const FORCED_PREVIEW = DEMO_DATA && MODE !== 'preview';
if (FORCED_PREVIEW) MODE = 'preview';

const OWNER_SLACK = {};
Object.keys(OWNER_SLACK_IDS || {}).forEach(function (k) {
  const v = String(OWNER_SLACK_IDS[k] || '').trim();
  if (v) OWNER_SLACK[String(k)] = v;
});

const BASE_URL = 'https://' + (COMPANY_DOMAIN.trim() || 'api') + '.pipedrive.com/api/v1';

// Every field key this workflow is configured to touch, gathered here so the PHI check runs
// in one place rather than at each use.
const TOUCHED_FIELDS = []
  .concat(Object.keys(RESULT_FIELDS).map(function (k) {
    return { role: 'result', name: k, key: RESULT_FIELDS[k] };
  }))
  .concat(Object.keys(CONTEXT_FIELDS).map(function (k) {
    return { role: 'context', name: k, key: CONTEXT_FIELDS[k] };
  }))
  .filter(function (f) { return String(f.key || '').trim() !== ''; });

return [{
  json: {
    base_url:       BASE_URL,
    api_token:      API_TOKEN.trim(),
    company_domain: COMPANY_DOMAIN.trim(),
    pipeline_id:    String(PIPELINE_ID || '').trim(),
    max_pages:      Math.max(1, Number(MAX_PAGES) || 20),

    stages:              STAGES,
    activity_types:      ACTIVITY_TYPES,
    reengage_after_days: Number(REENGAGE_AFTER_DAYS) || 60,
    reengage_type:       REENGAGE_TYPE,
    reengage_subject:    REENGAGE_SUBJECT,

    horizon_days:        Number(HORIZON_DAYS) || 45,
    grace_hours:         Number(GRACE_HOURS) || 0,
    daily_cap:           Number(DAILY_CAP) || 0,
    overdue_days:        Number(OVERDUE_DAYS) || 0,
    manager_after_days:  Number(MANAGER_AFTER_DAYS) || 0,
    remind_manager_after_days: Number(REMIND_MANAGER_AFTER_DAYS) || 0,
    max_per_owner_per_day: Number(MAX_PER_OWNER_PER_DAY) || 0,
    level_within_days:   Number(LEVEL_WITHIN_DAYS) || 0,
    work_days:           (WORK_DAYS || []).map(Number),
    holidays:            (HOLIDAYS || []).map(function (h) { return String(h).slice(0, 10); }),
    high_priority_value: Number(HIGH_PRIORITY_VALUE) || 0,

    forbidden_field_words: FORBIDDEN_FIELD_WORDS.map(function (w) {
      return String(w).toLowerCase();
    }),
    result_fields:  RESULT_FIELDS,
    context_fields: CONTEXT_FIELDS,
    touched_fields: TOUCHED_FIELDS,

    sheet_id:        SHEET_ID.trim(),
    dashboard_tab:   DASHBOARD_TAB,
    gaps_tab:        GAPS_TAB,
    by_rep_tab:      BY_REP_TAB,
    by_practice_tab: BY_PRACTICE_TAB,
    dashboard_columns:   DASHBOARD_COLUMNS,
    gap_columns:         GAP_COLUMNS,
    by_rep_columns:      BY_REP_COLUMNS,
    by_practice_columns: BY_PRACTICE_COLUMNS,

    outreach_types:     OUTREACH_TYPES,
    conversation_types: CONVERSATION_TYPES,
    meeting_types:      MEETING_TYPES,
    no_answer_words:    NO_ANSWER_WORDS.map(function (w) { return String(w).toLowerCase(); }),
    partner_stages:     PARTNER_STAGES,
    report_window_days: Number(REPORT_WINDOW_DAYS) || 7,
    baseline_min_days:  Number(BASELINE_MIN_DAYS) || 5,
    coach_min_attempts:         Number(COACH_MIN_ATTEMPTS) || 0,
    coach_min_conversation_pct: Number(COACH_MIN_CONVERSATION_PCT) || 0,
    coach_max_gap_pct:          Number(COACH_MAX_GAP_PCT) || 100,

    alert_webhook_url:   ALERT_WEBHOOK_URL.trim(),
    manager_webhook_url: MANAGER_WEBHOOK_URL.trim(),
    test_owner_id:       String(TEST_OWNER_ID || '').trim(),
    owner_slack_ids:     OWNER_SLACK,

    // derived flags — the gates read these, never the raw constants
    mode:         MODE,
    preview_only: MODE === 'preview',
    test_write:   MODE === 'test',
    live_write:   MODE === 'live',

    pipedrive_enabled: API_TOKEN.trim() !== '' && COMPANY_DOMAIN.trim() !== '',
    write_enabled:     MODE !== 'preview' && API_TOKEN.trim() !== ''
                       && COMPANY_DOMAIN.trim() !== '',
    sheet_enabled:   SHEET_ID.trim() !== '',
    // Fabricated demo numbers never land in a real sheet, and are never compared with it.
    sheet_live:      SHEET_ID.trim() !== '' && !DEMO_DATA,
    slack_dm_enabled: SLACK_DMS === true && Object.keys(OWNER_SLACK).length > 0,
    failure_alert_enabled: (ALERT_WEBHOOK_URL.trim() || MANAGER_WEBHOOK_URL.trim()) !== '',
    failure_url:     ALERT_WEBHOOK_URL.trim() || MANAGER_WEBHOOK_URL.trim(),
    alert_enabled:   ALERT_WEBHOOK_URL.trim() !== '',
    manager_enabled: (MANAGER_WEBHOOK_URL.trim() || ALERT_WEBHOOK_URL.trim()) !== '',
    manager_url:     MANAGER_WEBHOOK_URL.trim() || ALERT_WEBHOOK_URL.trim(),
    demo_data:       DEMO_DATA,
    forced_preview:  FORCED_PREVIEW
  }
}];

// Folds every page of the three Pipedrive reads into ONE item shaped
// {deals, activities, deal_fields, read_ok, failures}.
//
// The reads are paginated by the HTTP nodes themselves (500 rows a page, Pipedrive's
// maximum), so each node hands over one item PER PAGE. Everything downstream — the guard,
// the KPIs, the dashboard — reads this shape and never touches a Pipedrive response
// directly, so the demo pipeline and the real account are interchangeable from here on.
//
// The one dangerous mistake this workflow can make is reporting a pipeline it failed to
// read as a pipeline with nothing wrong in it. So a read is only OK when EVERY page came
// back success:true AND the last page says there is nothing more. A 402, a timeout, a
// rate limit, or MAX_PAGES cutting the read short all set read_ok = false, and the run is
// routed to the failure alert instead of the rule.
const cfg = $('config').first().json;

const failures = [];

function pagesOf(nodeName) {
  try { return $(nodeName).all().map(function (i) { return i.json || {}; }); }
  catch (e) { return []; }
}

function rows(nodeName, what, paginated) {
  const pages = pagesOf(nodeName);
  if (!pages.length) { failures.push(what + ': no response'); return []; }
  const out = [];
  let bad = 0;
  pages.forEach(function (p) {
    if (!p || p.success !== true) {
      bad++;
      const msg = p && (p.error && (p.error.message || p.error)) || (p && p.error_info) ||
        'no usable response';
      if (bad === 1) failures.push(what + ': ' + String(msg).slice(0, 200));
      return;
    }
    (Array.isArray(p.data) ? p.data : []).forEach(function (r) { out.push(r); });
  });
  const last = pages[pages.length - 1] || {};
  const more = last.additional_data && last.additional_data.pagination &&
    last.additional_data.pagination.more_items_in_collection === true;
  if (!bad && more) {
    failures.push(what + ': stopped at ' + pages.length + ' page(s) with more still to read' +
      (paginated ? ' — raise MAX_PAGES in config' : ''));
  }
  return out;
}

const dealRows = rows('[cred] Pipedrive - open deals', 'deals', true);
const actRows = rows('[cred] Pipedrive - activities', 'activities', true);
const fieldRows = rows('[cred] Pipedrive - deal fields', 'deal fields', false);

const stageById = {};
cfg.stages.forEach(function (s) { stageById[String(s.id)] = s; });

function normaliseDeal(d) {
  const stage = stageById[String(d.stage_id)] || { name: 'Unknown stage', next_type: '',
    due_in_days: 7, stale_days: 30, subject: 'Next step' };
  return {
    id: d.id,
    title: d.title || ('Deal ' + d.id),
    stage_id: d.stage_id,
    stage: stage.name,
    status: d.status || 'open',
    value: Number(d.value || 0),
    currency: d.currency || '',
    owner_id: (d.user_id && d.user_id.id) || d.user_id || null,
    owner: (d.user_id && d.user_id.name) || 'Unassigned',
    org_id: (d.org_id && d.org_id.value) || d.org_id || null,
    organisation: (d.org_id && d.org_id.name) || d.org_name || '',
    person_id: (d.person_id && d.person_id.value) || d.person_id || null,
    person: (d.person_id && d.person_id.name) || d.person_name || '',
    add_time: d.add_time || null,
    stage_change_time: d.stage_change_time || d.add_time || null,
    // Kept whole so the result fields can be read by key later, once the PHI check has
    // said which keys are allowed.
    raw: d
  };
}

function normaliseActivity(a) {
  return {
    id: a.id,
    deal_id: a.deal_id || null,
    type: a.type || '',
    subject: a.subject || '',
    note: a.note || '',
    done: a.done === true || a.done === 1,
    due_date: a.due_date || null,
    due_time: a.due_time || '',
    marked_done_time: a.marked_done_time || null,
    add_time: a.add_time || null,
    owner_id: a.user_id || null
  };
}

// Pagination by offset can return the same row twice if a deal changes while the pages are
// being read. De-duplicate by id so a deal is never counted, or acted on, twice.
function uniqueById(list) {
  const seen = {};
  return list.filter(function (r) {
    const k = String(r && r.id);
    if (seen[k]) return false;
    seen[k] = true;
    return true;
  });
}

const deals = uniqueById(dealRows).filter(function (d) {
  if (String(d.status || 'open') !== 'open') return false;
  if (!cfg.pipeline_id) return true;
  return String(d.pipeline_id) === String(cfg.pipeline_id);
}).map(normaliseDeal);

return [{
  json: {
    source: 'pipedrive',
    read_at: new Date().toISOString(),
    read_ok: failures.length === 0,
    failures: failures,
    pages: {
      deals: pagesOf('[cred] Pipedrive - open deals').length,
      activities: pagesOf('[cred] Pipedrive - activities').length
    },
    deals: deals,
    activities: uniqueById(actRows).map(normaliseActivity),
    deal_fields: fieldRows.map(function (f) {
      return { key: f.key, name: f.name || '' };
    })
  }
}];

// STOP: Pipedrive is not configured — build the demo pipeline instead.
//
// Deterministic, so the same run produces the same couple of dozen deals every time and a
// screen-share can be rehearsed. The spread is deliberate: roughly a third of the deals are
// missing a next activity, a few are overdue rather than missing, one referral partner has
// gone quiet past the re-engagement threshold, and one high-value deal has stalled — every
// branch of the guard has something to do.
//
// Nothing here can reach Pipedrive: `demo_data` forces the run into preview in config.
const cfg = $('config').first().json;

if (cfg.pipedrive_enabled) {
  throw new Error('demo pipeline reached with Pipedrive configured — check the IF gate');
}
if (!cfg.demo_data) {
  return [{ json: { source: 'none', read_at: new Date().toISOString(), read_ok: true, failures: [],
    deals: [], activities: [], deal_fields: [],
    _note: 'No API token and DEMO_PIPELINE is off. Nothing to work on.' } }];
}

const DAY = 86400000;
const now = Date.now();
function iso(ms) { return new Date(ms).toISOString().slice(0, 19).replace('T', ' '); }
function date(ms) { return new Date(ms).toISOString().slice(0, 10); }

const PRACTICES = [
  ['Riverbend Pain & Spine', 'Dr. A. Whitfield', 'Pain management'],
  ['Northgate Neurology Associates', 'Dr. P. Iyer', 'Neurology'],
  ['Cedar Hollow Orthopaedics', 'Dr. M. Okonkwo', 'Orthopaedics'],
  ['Lakeshore Rehabilitation Group', 'Dr. S. Duval', 'Physical medicine'],
  ['Fairview Family Practice', 'Dr. R. Castellanos', 'Primary care'],
  ['Summit Pain Institute', 'Dr. K. Baruah', 'Pain management'],
  ['Harbour Point Rheumatology', 'Dr. J. Lindqvist', 'Rheumatology'],
  ['Westfield Sports Medicine', 'Dr. T. Nakamura', 'Sports medicine']
];
const REPS = [
  { id: 11, name: 'Dana Reyes' },
  { id: 12, name: 'Marcus Hale' },
  { id: 13, name: 'Priya Venn' }
];

// A tiny deterministic PRNG so the fixture never shifts between runs.
let seed = 20260902;
function rnd() { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }
function pick(list) { return list[Math.floor(rnd() * list.length)]; }

const deals = [];
const activities = [];
const managerTierIds = [];
let dealId = 3000;
let actId = 9000;

cfg.stages.forEach(function (stage, si) {
  const count = si < 3 ? 4 : 2;   // top of the funnel is wider, as a real pipeline is
  for (let i = 0; i < count; i++) {
    const practice = PRACTICES[(si * 3 + i) % PRACTICES.length];
    const rep = REPS[(si + i) % REPS.length];
    const age = Math.floor(rnd() * 40) + 2;
    const id = ++dealId;

    deals.push({
      id: id,
      title: practice[0] + ' — CRPS referral network',
      stage_id: stage.id,
      stage: stage.name,
      status: 'open',
      value: si >= 6 ? 40000 : Math.floor(rnd() * 20000) + 3000,
      currency: 'USD',
      owner_id: rep.id,
      owner: rep.name,
      org_id: 500 + ((si * 3 + i) % PRACTICES.length),
      organisation: practice[0],
      person_id: 700 + ((si * 3 + i) % PRACTICES.length),
      person: practice[1],
      add_time: iso(now - age * DAY),
      stage_change_time: iso(now - Math.floor(age / 2) * DAY),
      raw: { id: id, specialty: practice[2] }
    });

    // A past activity, always. This is what "days quiet" is measured from.
    const quiet = Math.floor(rnd() * (stage.stale_days + 20));
    activities.push({
      id: ++actId, deal_id: id, type: 'initial_call',
      subject: 'Outreach call', note: rnd() < 0.35 ? 'No answer, left message' : 'Spoke with the practice manager',
      done: true, due_date: date(now - quiet * DAY), due_time: '',
      marked_done_time: iso(now - quiet * DAY), add_time: iso(now - quiet * DAY),
      owner_id: rep.id
    });

    // The interesting part: who has a next step and who does not.
    const roll = rnd();
    if (roll < 0.34) {
      // No open activity at all — this is what the guard exists to catch.
    } else if (roll < 0.5) {
      // Open but overdue. The guard escalates rather than stacking another task on top.
      // Odd deal ids are a few days late (owner tier); even ones are two weeks late
      // (manager tier), so both escalation tiers have something to do.
      const lateDays = id % 2 === 0 ? cfg.manager_after_days * 2 : cfg.overdue_days + 2;
      if (id % 2 === 0) managerTierIds.push(id);
      activities.push({
        id: ++actId, deal_id: id, type: stage.next_type || 'follow_up_call',
        subject: stage.subject || 'Next step', note: '',
        done: false, due_date: date(now - lateDays * DAY), due_time: '09:00',
        marked_done_time: null, add_time: iso(now - 10 * DAY), owner_id: rep.id
      });
    } else if (roll < 0.6) {
      // Open, but parked so far out it is not a next step in any meaningful sense.
      activities.push({
        id: ++actId, deal_id: id, type: 'follow_up_call',
        subject: 'Check back next year', note: '',
        done: false, due_date: date(now + (cfg.horizon_days + 60) * DAY), due_time: '09:00',
        marked_done_time: null, add_time: iso(now - 3 * DAY), owner_id: rep.id
      });
    } else {
      // Properly covered.
      activities.push({
        id: ++actId, deal_id: id, type: stage.next_type || 'follow_up_call',
        subject: stage.subject || 'Next step', note: '',
        done: false, due_date: date(now + Math.floor(rnd() * 10 + 1) * DAY), due_time: '10:00',
        marked_done_time: null, add_time: iso(now - 2 * DAY), owner_id: rep.id
      });
    }
  }
});

// One referral partner that has gone quiet well past the re-engagement threshold, built
// explicitly rather than left to the random spread — the re-engagement branch has to have
// something to do every single time this is demonstrated.
const quietStage = cfg.stages.filter(function (s) {
  return cfg.partner_stages.indexOf(s.name) !== -1;
}).pop() || cfg.stages[cfg.stages.length - 1];
const quietAge = cfg.reengage_after_days + 15;
const quietId = ++dealId;
deals.push({
  id: quietId,
  title: 'Marchetti Interventional Pain — CRPS referral network',
  stage_id: quietStage.id,
  stage: quietStage.name,
  status: 'open',
  value: 38000,
  currency: 'USD',
  owner_id: REPS[0].id,
  owner: REPS[0].name,
  org_id: 599,
  organisation: 'Marchetti Interventional Pain',
  person_id: 799,
  person: 'Dr. L. Marchetti',
  add_time: iso(now - 400 * DAY),
  stage_change_time: iso(now - 300 * DAY),
  raw: { id: quietId, specialty: 'Pain management' }
});
activities.push({
  id: ++actId, deal_id: quietId, type: 'referral_follow_up',
  subject: 'Referral check-in', note: 'Practice has not referred since the spring',
  done: true, due_date: date(now - quietAge * DAY), due_time: '',
  marked_done_time: iso(now - quietAge * DAY), add_time: iso(now - quietAge * DAY),
  owner_id: REPS[0].id
});

// Activity inside the reporting window, so the weekly dashboard has real numbers rather
// than the two that happen to fall inside seven days by chance. Roughly a third of these
// are no-answers, which is what makes "attempts" and "conversations" different columns.
deals.forEach(function (d, i) {
  if (d.id === quietId) return;   // the whole point of that one is that it is quiet
  if (i % 2 !== 0) return;
  const daysAgo = (i % Number(cfg.report_window_days || 7));
  const noAnswer = i % 3 === 0;
  activities.push({
    id: ++actId, deal_id: d.id,
    type: i % 4 === 0 ? 'follow_up_call' : 'email',
    subject: i % 4 === 0 ? 'Follow-up call' : 'Study information email',
    note: noAnswer ? 'No answer, left message with the front desk'
                   : 'Spoke with the practice manager about the CRPS protocol',
    done: true, due_date: date(now - daysAgo * DAY), due_time: '',
    marked_done_time: iso(now - daysAgo * DAY), add_time: iso(now - daysAgo * DAY),
    owner_id: d.owner_id
  });
  if (i % 6 === 0) {
    activities.push({
      id: ++actId, deal_id: d.id, type: 'physician_meeting',
      subject: 'Physician meeting', note: 'Reviewed inclusion criteria',
      done: true, due_date: date(now - daysAgo * DAY), due_time: '',
      marked_done_time: iso(now - daysAgo * DAY), add_time: iso(now - daysAgo * DAY),
      owner_id: d.owner_id
    });
  }
});

// The guard's memory, seeded so the demo shows de-duplication on its very first run:
// one manager-tier deal was escalated yesterday (not repeated today), one was escalated
// nine days ago and is still open (a reminder), and one has since been resolved.
const byId = {};
deals.forEach(function (d) { byId[d.id] = d; });
const demoMemory = { escalated: {}, runs: [
  { date: date(now - 8 * DAY), coverage_pct: 41, uncovered: 14, overdue: 6 },
  { date: date(now - 1 * DAY), coverage_pct: 48, uncovered: 13, overdue: 5 }
] };
if (managerTierIds[0]) {
  demoMemory.escalated[managerTierIds[0]] = { first: date(now - DAY), last: date(now - DAY),
    organisation: byId[managerTierIds[0]].organisation };
}
if (managerTierIds[1]) {
  demoMemory.escalated[managerTierIds[1]] = { first: date(now - 9 * DAY),
    last: date(now - 9 * DAY), organisation: byId[managerTierIds[1]].organisation };
}
demoMemory.escalated['999'] = { first: date(now - 6 * DAY), last: date(now - 6 * DAY),
  organisation: 'Old Mill Pain Clinic' };

// Last week's Dashboard row, as workflow 02 would read it back from the sheet, so the
// week-over-week comparison has something to compare with before a sheet exists.
const demoBaseline = {
  run_at: iso(now - 7 * DAY), open_deals: deals.length - 2, covered: 10, gaps: 11,
  coverage_pct: 48, overdue: 7, outreach_attempts: 9, conversations: 3, meetings: 1,
  new_partners: 0, active_partners: null, stalled: 9, high_priority: 3
};

return [{
  json: {
    source: 'demo',
    read_at: new Date().toISOString(),
    read_ok: true,
    failures: [],
    _demo_memory: demoMemory,
    _demo_baseline: demoBaseline,
    deals: deals,
    activities: activities,
    // Field names only, which is all the PHI check needs. Deliberately clean — see the
    // README for how to prove the check bites by pointing a config key at a bad field.
    deal_fields: [
      { key: 'title', name: 'Title' },
      { key: 'value', name: 'Value' },
      { key: 'a1b2c3d4e5f60718293a4b5c6d7e8f9012345678', name: 'Specialty' },
      { key: 'b2c3d4e5f60718293a4b5c6d7e8f90123456789a', name: 'Territory' },
      { key: 'c3d4e5f60718293a4b5c6d7e8f90123456789ab2', name: 'Study code' },
      { key: 'd4e5f60718293a4b5c6d7e8f90123456789ab2c3', name: 'Referrals sent (count)' }
    ],
    _note: 'DEMO PIPELINE — ' + deals.length + ' fabricated deals. The run is forced into ' +
           'preview; nothing here can reach a Pipedrive account.'
  }
}];

// The Pipedrive read failed, or was cut short. This is NOT a quiet day, and it must never
// look like one.
//
// Without this branch the guard's worst failure is invisible: a 401 or a rate limit comes
// back as an empty list, the rule finds "no uncovered deals", and the summary says the
// pipeline is fully covered. So a failed read gets its own message, naming the call that
// failed and what Pipedrive said, and the run then ends as a FAILED execution so n8n's
// own error workflow (if you have one) sees it too.
const cfg = $('config').first().json;
const p = $json;
const failures = p.failures || ['unknown read failure'];

const lines = [];
lines.push(':x: *Pipedrive read FAILED — the rule was not checked today*');
failures.forEach(function (f) { lines.push('• ' + f); });
lines.push('');
lines.push('Nothing was created, escalated or reported. This is not a clean pipeline — it is ' +
  'a pipeline nobody looked at. Check the API token and COMPANY_DOMAIN in config, then run ' +
  'it again.');
if (p.pages) {
  lines.push('Pages read before it stopped: deals ' + (p.pages.deals || 0) + ', activities ' +
    (p.pages.activities || 0) + '.');
}

return [{
  json: {
    read_ok: false,
    failures: failures,
    read_at: p.read_at,
    mode: cfg.mode,
    _failure_body: { text: lines.join('\n') },
    summary: lines.join('\n')
  }
}];

// STOP: end the execution as FAILED.
//
// The alert (if a webhook is set) has already gone out. Throwing here marks the execution
// red in n8n's list and triggers the instance's error workflow, so a broken token cannot
// hide behind a run history full of green ticks.
const f = $('build the read-failure alert').first().json;
throw new Error('Pipedrive read failed — rule not checked: ' + (f.failures || []).join('; '));

// The compliance requirement, enforced rather than documented.
//
// "Do not create fields for identifiable patient medical information, diagnoses,
//  medications, screening responses, medical records or other patient PHI."
//
// Two different things can go wrong, and they deserve two different reactions:
//
//   1. The CRM already contains a field whose NAME looks like PHI. That is not this
//      workflow's doing. It is reported, loudly, in every run summary — and the field is
//      added to a blocklist so nothing here ever reads it.
//
//   2. This workflow is CONFIGURED to read one of those fields. That is our mistake, and
//      the run stops. A misconfiguration that quietly copies a diagnosis into a dashboard
//      is exactly the failure the client wrote the requirement to prevent.
//
// Aggregate recruitment results — counts of referrals, screens, enrolments — are in scope
// and are not caught by this: a number of patients is not a patient.
const cfg = $('config').first().json;
const pipeline = $json;

const words = cfg.forbidden_field_words || [];
const fields = pipeline.deal_fields || [];

function looksLikePhi(name) {
  const n = String(name || '').toLowerCase();
  for (let i = 0; i < words.length; i++) {
    const w = words[i];
    // Short keys like 'dob', 'mrn', 'phi' and 'ssn' are matched as whole words, so a field
    // called "Method of introduction" is not flagged for containing "dob"... it does not,
    // but "Doctor of birth cohort" style names and abbreviations inside longer words are a
    // real source of false positives, and a check that cries wolf gets switched off.
    const whole = w.length <= 4;
    const hit = whole
      ? new RegExp('(^|[^a-z])' + w + '([^a-z]|$)').test(n)
      : n.indexOf(w) !== -1;
    if (hit) return w;
  }
  return '';
}

const violations = [];
const blocked = {};
fields.forEach(function (f) {
  const word = looksLikePhi(f.name);
  if (word) {
    blocked[f.key] = true;
    violations.push({ key: f.key, name: f.name, matched: word });
  }
});

// The second check: is this workflow pointed at one of them?
const misconfigured = [];
(cfg.touched_fields || []).forEach(function (t) {
  const field = fields.filter(function (f) { return f.key === t.key; })[0];
  const name = field ? field.name : '';
  const word = looksLikePhi(name || t.name);
  if (word) {
    misconfigured.push(t.role + '.' + t.name + ' -> "' + (name || t.key) +
      '" (matched "' + word + '")');
  }
});

if (misconfigured.length) {
  throw new Error(
    'PHI boundary: this workflow is configured to read ' + misconfigured.length +
    ' field(s) that look like patient clinical data — ' + misconfigured.join('; ') +
    '. Pipedrive is the physician/practice CRM, not the patient database. Fix ' +
    'RESULT_FIELDS / CONTEXT_FIELDS in config before running again.');
}

// Which result fields are actually captured. A blank key is reported as "not captured",
// never as a zero — a zero is a finding, an absence is a gap in the CRM setup.
const resultFields = {};
const notCaptured = [];
Object.keys(cfg.result_fields || {}).forEach(function (name) {
  const key = String(cfg.result_fields[name] || '').trim();
  if (!key) { notCaptured.push(name); return; }
  if (blocked[key]) { notCaptured.push(name + ' (blocked: field name looks like PHI)'); return; }
  resultFields[name] = key;
});

return [{
  json: Object.assign({}, pipeline, {
    phi_violations: violations,
    phi_blocked_keys: Object.keys(blocked),
    result_field_keys: resultFields,
    results_not_captured: notCaptured,
    phi_ok: true
  })
}];

// THE RULE: no open opportunity should exist without a next activity.
//
// Fans the one pipeline item out into one item per open deal, each carrying the verdict.
// A deal is COVERED when it has at least one activity that is:
//
//   - not done, and
//   - due on or before HORIZON_DAYS from today.
//
// The horizon is the part that matters. Without it, "next activity" is satisfied by a task
// parked eleven months out, and the report says 100% while the pipeline rots. With it, a
// parked task reads as uncovered, which is the truth.
//
// Overdue is measured in BUSINESS days (WORK_DAYS + HOLIDAYS), so a task due on Friday is
// one day late on Monday, not three, and the escalation tiers do not fire on weekends.
const cfg = $('config').first().json;
const pipeline = $json;

// ---- business-day calendar (WORK_DAYS + HOLIDAYS from config). Inlined by build/build.mjs
// into every node that counts days, so "3 days overdue" means the same thing everywhere.
function businessCalendar(c) {
  const DAY = 86400000;
  const work = (c.work_days && c.work_days.length) ? c.work_days : [1, 2, 3, 4, 5];
  const holidays = {};
  (c.holidays || []).forEach(function (h) { holidays[String(h).slice(0, 10)] = true; });
  function ymd(ms) { return new Date(ms).toISOString().slice(0, 10); }
  function dayStart(ms) { return Date.parse(ymd(ms) + 'T00:00:00Z'); }
  function isWorkday(ms) {
    return work.indexOf(new Date(ms).getUTCDay()) !== -1 && !holidays[ymd(ms)];
  }
  // n business days after the day of `ms`. n = 0 means "today, or the next workday".
  function add(ms, n) {
    let t = dayStart(ms);
    let left = Math.max(0, Math.round(Number(n) || 0));
    let guard = 0;
    while (left > 0 && guard++ < 3660) { t += DAY; if (isWorkday(t)) left--; }
    while (!isWorkday(t) && guard++ < 3660) t += DAY;
    return t;
  }
  // Business days that have passed between the day of `from` and the day of `to`.
  // Due Friday, asked Monday = 1, not 3.
  function between(from, to) {
    let t = dayStart(from);
    const end = dayStart(to);
    let n = 0;
    let guard = 0;
    while (t < end && guard++ < 3660) { t += DAY; if (isWorkday(t)) n++; }
    return n;
  }
  return { DAY: DAY, ymd: ymd, dayStart: dayStart, isWorkday: isWorkday, add: add,
    between: between };
}
const cal = businessCalendar(cfg);

const DAY = 86400000;
const now = Date.now();
const today = cal.dayStart(now);
const horizon = now + Number(cfg.horizon_days || 45) * DAY;
const graceFrom = now - Number(cfg.grace_hours || 0) * 3600000;

function parseDate(d, t) {
  if (!d) return null;
  const stamp = String(d).slice(0, 10) + 'T' + (String(t || '').slice(0, 5) || '00:00') + ':00Z';
  const ms = Date.parse(stamp);
  return isNaN(ms) ? null : ms;
}

function parseStamp(s) {
  if (!s) return null;
  const ms = Date.parse(String(s).replace(' ', 'T') + (String(s).indexOf('Z') === -1 ? 'Z' : ''));
  return isNaN(ms) ? null : ms;
}

const byDeal = {};
(pipeline.activities || []).forEach(function (a) {
  if (!a.deal_id) return;
  const k = String(a.deal_id);
  if (!byDeal[k]) byDeal[k] = [];
  byDeal[k].push(a);
});

const stageByName = {};
(cfg.stages || []).forEach(function (s) { stageByName[s.name] = s; });

const out = [];
let covered = 0;
let uncovered = 0;
let parked = 0;
let overdueOnly = 0;
let highStalled = 0;

(pipeline.deals || []).forEach(function (deal) {
  const acts = byDeal[String(deal.id)] || [];
  const open = acts.filter(function (a) { return !a.done; });

  let nextDue = null;
  let parkedDue = null;
  let lateDue = null;   // earliest open activity whose due DAY is already behind us
  open.forEach(function (a) {
    const due = parseDate(a.due_date, a.due_time);
    if (due === null) return;
    if (due <= horizon) {
      if (nextDue === null || due < nextDue) nextDue = due;
      if (cal.dayStart(due) < today && (lateDue === null || due < lateDue)) lateDue = due;
    } else if (parkedDue === null || due < parkedDue) {
      parkedDue = due;
    }
  });

  // An activity with no due date at all is not a next step either — it never surfaces on
  // anyone's day. Counted with the parked ones.
  const undated = open.filter(function (a) { return !a.due_date; }).length;
  if (undated && parkedDue === null) parkedDue = horizon + DAY;

  const overdueBdays = lateDue === null ? 0 : cal.between(lateDue, now);
  const isOverdue = lateDue !== null && overdueBdays >= Number(cfg.overdue_days || 0);

  const done = acts.filter(function (a) { return a.done; })
    .map(function (a) { return parseStamp(a.marked_done_time) || parseDate(a.due_date, a.due_time); })
    .filter(function (ms) { return ms !== null; })
    .sort(function (a, b) { return b - a; });
  const lastActivity = done.length ? done[0] : parseStamp(deal.add_time);
  const daysQuiet = lastActivity ? Math.floor((now - lastActivity) / DAY) : null;

  const stage = stageByName[deal.stage] || {};
  const added = parseStamp(deal.add_time);
  const inGrace = added !== null && added > graceFrom;

  const isCovered = nextDue !== null;
  const stale = daysQuiet !== null && daysQuiet >= Number(stage.stale_days || 30);
  const highValue = Number(deal.value || 0) >= Number(cfg.high_priority_value || 0);
  if (isCovered) covered++; else uncovered++;
  if (!isCovered && parkedDue !== null) parked++;
  if (isCovered && isOverdue) overdueOnly++;
  if (stale && highValue) highStalled++;

  out.push({
    json: Object.assign({}, deal, {
      covered: isCovered,
      in_grace: inGrace,
      next_due: nextDue ? new Date(nextDue).toISOString().slice(0, 10) : '',
      parked_due: parkedDue ? new Date(parkedDue).toISOString().slice(0, 10) : '',
      overdue_due: lateDue ? new Date(lateDue).toISOString().slice(0, 10) : '',
      overdue_business_days: overdueBdays,
      overdue: isOverdue,
      open_activities: open.length,
      last_activity: lastActivity ? new Date(lastActivity).toISOString().slice(0, 10) : '',
      days_quiet: daysQuiet,
      stale: stale,
      high_priority: highValue,
      _pipeline: {
        read_at: pipeline.read_at, source: pipeline.source,
        phi_violations: pipeline.phi_violations || [],
        results_not_captured: pipeline.results_not_captured || []
      }
    })
  });
});

const totals = {
  open_deals: (pipeline.deals || []).length,
  covered: covered,
  uncovered: uncovered,
  parked: parked,
  overdue_but_covered: overdueOnly,
  high_value_stalled: highStalled
};

// Anything for the guard to do: a gap to fill, an overdue deal to escalate, or a
// high-value deal gone stale. Every deal item carries the same flag, so the IF after this
// node routes the whole batch one way.
const hasWork = uncovered > 0 || overdueOnly > 0 || highStalled > 0;

// No open deals at all is still a run, and still needs a summary — silence would be
// indistinguishable from a workflow that stopped working.
if (!out.length) {
  return [{
    json: {
      _has_work: false,
      _totals: totals,
      source: pipeline.source,
      read_at: pipeline.read_at,
      phi_violations: pipeline.phi_violations || [],
      results_not_captured: pipeline.results_not_captured || [],
      _note: 'No open deals in this pipeline.'
    }
  }];
}

out.forEach(function (item) {
  item.json._has_work = hasWork;
  item.json._totals = totals;
});
return out;

// STOP: the rule already holds.
//
// Every open deal has an activity that is not done and is due inside the horizon, nothing
// is overdue past OVERDUE_DAYS and no high-value deal has gone stale. Nothing to create and
// nothing to escalate. This still produces a summary — a guard that goes silent when it
// finds nothing is indistinguishable from a guard that has stopped running, and the second
// one is the expensive failure.
const cfg = $('config').first().json;
const j = $input.first().json;
const t = j._totals || {};

return [{
  json: {
    _clean: true,
    source: j.source || (j._pipeline && j._pipeline.source),
    read_at: j.read_at || (j._pipeline && j._pipeline.read_at),
    totals: t,
    phi_violations: j.phi_violations || (j._pipeline && j._pipeline.phi_violations) || [],
    results_not_captured: j.results_not_captured ||
      (j._pipeline && j._pipeline.results_not_captured) || [],
    decisions: [],
    headline: t.open_deals
      ? 'All ' + t.open_deals + ' open deals have a next activity within ' +
        cfg.horizon_days + ' days, and none is overdue.'
      : 'No open deals in this pipeline.',
    recorded_at: new Date().toISOString()
  }
}];

// What the guard would do about each deal, decided before anything is written.
//
// Four outcomes, and only two of them create anything:
//
//   create      no next step within the horizon -> schedule the one this stage calls for
//   reengage    a referral partner that has gone quiet -> a different activity entirely
//   escalate    there IS a next step but it is overdue -> tier "owner" (the rep's DM) or,
//               past MANAGER_AFTER_DAYS, tier "manager". Never a second task stacked on
//               top of the one the rep is already ignoring.
//   skip        covered, in its grace window, past the daily cap, or a stage with no rule
//
// Due dates are BUSINESS days from today, then load-levelled per rep: a rep who already has
// MAX_PER_OWNER_PER_DAY open activities due that day gets the new one on the next business
// day with room (at most LEVEL_WITHIN_DAYS later). The cap is enforced here, in code, and
// items are ordered worst-first so that if it bites, it bites on the deals that matter least.
const cfg = $('config').first().json;
const items = $input.all();

// ---- business-day calendar (WORK_DAYS + HOLIDAYS from config). Inlined by build/build.mjs
// into every node that counts days, so "3 days overdue" means the same thing everywhere.
function businessCalendar(c) {
  const DAY = 86400000;
  const work = (c.work_days && c.work_days.length) ? c.work_days : [1, 2, 3, 4, 5];
  const holidays = {};
  (c.holidays || []).forEach(function (h) { holidays[String(h).slice(0, 10)] = true; });
