  // Due Friday, asked Monday = 1, not 3.
  function between(from, to) {
    let t = dayStart(from);
    const end = dayStart(to);
    let n = 0;
    let guard = 0;
    while (t < end && guard++ < 3660) { t += DAY; if (isWorkday(t)) n++; }
    return n;
  }
  return { DAY: DAY, ymd: ymd, dayStart: dayStart, isWorkday: isWorkday, add: add,
