        type: type,
        due_date: when.date,
        due_time: '09:00',
        duration: '00:30',
        deal_id: deal.id,
        person_id: deal.person_id || undefined,
        org_id: deal.org_id || undefined,
        user_id: assignTo || undefined,
        note: 'Scheduled by the activity guard: ' + reason
      } : null
    })
  });
});

return out;

// Reads Pipedrive's answer to each create and turns it into one honest line.
//
// A create that came back with success:false is NOT recorded as done. It is recorded as
// failed, with whatever Pipedrive said, and the deal stays uncovered so the next run picks
// it up again. The alternative — treating a 4xx as "handled" — is how a coverage report
// slowly becomes fiction.
const cfg = $('config').first().json;
const deal = $('decide the next activity').item.json;
const resp = $json || {};

// `a && b && c` evaluates to c, not to true. Without the coercion `ok` is the new
// activity's numeric id, `ok === true` is false, and every successful create is
// recorded as a failure — a coverage report that only ever goes down.
const ok = resp.success === true && !!(resp.data && resp.data.id);

return [{
  json: Object.assign({}, deal, {
    written: ok === true,
    activity_id: ok ? resp.data.id : null,
    write_error: ok ? '' : (resp.error || resp.error_info || 'no id returned'),
    outcome: ok
      ? (cfg.test_write ? 'created (test — assigned to the test user)' : 'created')
      : 'FAILED to create',
    recorded_at: new Date().toISOString()
  })
}];

// STOP: nothing was written for this deal.
//
// Open this node to read the whole decision. In preview — how the workflow ships — every
// deal the guard WOULD have acted on is here, with the activity it would have created, the
// stage rule that produced it and the due date. That list is the deliverable of a first
// run: you read it, you disagree with three of them, you change the stage rules, you run
// it again. Nothing has touched the CRM yet.
const cfg = $('config').first().json;
const deal = $json;

const why = cfg.preview_only
  ? (cfg.forced_preview
    ? 'PREVIEW (forced — the demo pipeline cannot write to a real account)'
    : 'PREVIEW — TEST_RUN is true and TEST_OWNER_ID is blank')
  : deal.action === 'escalate'
    ? 'escalated to the ' + deal.escalation_tier + ', not created — a second task on an ' +
      'already-overdue deal helps nobody'
    : deal.action_reason;

return [{
  json: Object.assign({}, deal, {
    written: false,
    activity_id: null,
    write_error: '',
    outcome: deal.action === 'create' || deal.action === 'reengage'
      ? 'would ' + deal.action + ': ' + deal.activity_subject + ' (due ' + deal.activity_due + ')'
      : deal.action,
    held_because: why,
    recorded_at: new Date().toISOString()
  })
}];

// Folds the whole run into one item: the counts, the per-deal decision list, and the two
// escalation lists (owner tier and manager tier) that the three messages are built from.
// Produced whether or not anything was written.
const cfg = $('config').first().json;
const items = $input.all().map(function (i) { return i.json; });

// The "every deal is covered" path arrives as a single item with no per-deal decisions.
const clean = items.filter(function (j) { return j._clean === true; })[0];
const decisions = items.filter(function (j) { return j._clean !== true && j.id; });

const first = decisions[0] || clean || {};
const totals = (first._totals || (clean && clean.totals) || {});
const pipe = first._pipeline || {};

const createdOk = decisions.filter(function (d) { return d.written === true; });
const failed = decisions.filter(function (d) {
  return d.written === false && d.write_error;
});
const wouldCreate = decisions.filter(function (d) {
  return (d.action === 'create' || d.action === 'reengage') && d.written !== true;
});
const escalations = decisions.filter(function (d) { return d.action === 'escalate'; });
const stalled = decisions.filter(function (d) { return d.stale === true; });
const highStalled = decisions.filter(function (d) { return d.high_value_stalled === true; });
const shifted = decisions.filter(function (d) { return Number(d.due_shifted_by || 0) > 0; });
const overCapacity = decisions.filter(function (d) { return d.owner_over_capacity === true; });

const open = Number(totals.open_deals || 0);
const covered = Number(totals.covered || 0);
const coverage = open ? Math.round((covered / open) * 100) : 100;
// Coverage AFTER this run: what was covered already, plus what was actually written.
const coverageAfter = open ? Math.round(((covered + createdOk.length) / open) * 100) : 100;

function escRow(d, tier) {
  return {
    deal_id: d.id, deal: d.title, organisation: d.organisation, stage: d.stage,
    owner: d.owner, owner_id: d.owner_id, value: d.value, days_quiet: d.days_quiet,
    overdue_business_days: d.overdue_business_days || 0, overdue_since: d.overdue_due || '',
    tier: tier,
    why: d.action === 'escalate' ? d.action_reason
      : 'high-value deal (' + d.value + ') quiet ' + d.days_quiet + ' days, past its stage limit'
  };
