const rows = decisions.map(function (d) {
  return {
    deal_id: d.id,
    deal: d.title,
    practice: d.organisation,
    contact: d.person,
    stage: d.stage,
    rep: d.owner,
    rep_id: d.owner_id,
    value: d.value,
    days_quiet: d.days_quiet,
    covered_before: d.covered,
    action: d.action,
    tier: d.escalation_tier || '',
