  json: {
    mode: cfg.mode,
    run_date: new Date().toISOString().slice(0, 10),
    source: pipe.source || (clean && clean.source) || 'unknown',
    open_deals: open,
    covered_before: covered,
    uncovered_before: Number(totals.uncovered || 0),
    coverage_pct: coverage,
    coverage_pct_after: coverageAfter,
    created: createdOk.length,
    would_create: wouldCreate.length,
    load_levelled: shifted.length,
    escalated: escalations.length,
    stalled: stalled.length,
    high_priority_stalled: highStalled.length,
    failed: failed.length,
    skipped: decisions.filter(function (d) { return d.action === 'skip'; }).length,
    decisions: rows,
    owner_tier: ownerTier,
    manager_tier: managerTier,
    results_not_captured: first.results_not_captured || pipe.results_not_captured ||
      (clean && clean.results_not_captured) || [],
    summary_lines: lines
  }
}];

// The guard's memory: what it already told the manager, and what coverage was last time.
//
// Two problems this solves, both of which kill an escalation channel within a fortnight:
//
//   1. Repetition. The same twelve overdue deals sent to a manager every weekday morning is
//      how the channel gets muted. A manager-tier deal is sent ONCE, then again only when
//      REMIND_MANAGER_AFTER_DAYS business days pass with it still open. A deal that has
//      been resolved drops out of memory and is counted as resolved.
//   2. No direction. "61% covered" means nothing alone. Each run records its coverage, and
//      the summary says how it moved since the previous run.
//
// Memory lives in this workflow's static data — no database, no credential. n8n only
// persists static data for executions started by the schedule (not the Run button), and
// this node only WRITES it outside preview, so a preview can never suppress a real
// escalation. The demo pipeline carries a seeded memory so the de-duplication is visible
// on the very first demo run.
const cfg = $('config').first().json;
const s = $json;

// ---- business-day calendar (WORK_DAYS + HOLIDAYS from config). Inlined by build/build.mjs
// into every node that counts days, so "3 days overdue" means the same thing everywhere.
function businessCalendar(c) {
  const DAY = 86400000;
  const work = (c.work_days && c.work_days.length) ? c.work_days : [1, 2, 3, 4, 5];
  const holidays = {};
  (c.holidays || []).forEach(function (h) { holidays[String(h).slice(0, 10)] = true; });
  function ymd(ms) { return new Date(ms).toISOString().slice(0, 10); }
  function dayStart(ms) { return Date.parse(ymd(ms) + 'T00:00:00Z'); }
  function isWorkday(ms) {
    return work.indexOf(new Date(ms).getUTCDay()) !== -1 && !holidays[ymd(ms)];
  }
  // n business days after the day of `ms`. n = 0 means "today, or the next workday".
  function add(ms, n) {
    let t = dayStart(ms);
    let left = Math.max(0, Math.round(Number(n) || 0));
    let guard = 0;
    while (left > 0 && guard++ < 3660) { t += DAY; if (isWorkday(t)) left--; }
    while (!isWorkday(t) && guard++ < 3660) t += DAY;
    return t;
  }
  // Business days that have passed between the day of `from` and the day of `to`.
  // Due Friday, asked Monday = 1, not 3.
  function between(from, to) {
    let t = dayStart(from);
    const end = dayStart(to);
    let n = 0;
    let guard = 0;
    while (t < end && guard++ < 3660) { t += DAY; if (isWorkday(t)) n++; }
    return n;
  }
  return { DAY: DAY, ymd: ymd, dayStart: dayStart, isWorkday: isWorkday, add: add,
    between: between };
}
const cal = businessCalendar(cfg);

const today = s.run_date;
const now = Date.now();

const pipeline = $('one pipeline').first().json;
const store = $getWorkflowStaticData('global');
const demoMemory = pipeline.source === 'demo' ? pipeline._demo_memory : null;
const memory = demoMemory || {
  escalated: store.escalated || {},
  runs: store.runs || []
};
const escalated = JSON.parse(JSON.stringify(memory.escalated || {}));
const runs = (memory.runs || []).slice();

// ---------------------------------------------------------------- manager de-duplication
const remindAfter = Number(cfg.remind_manager_after_days || 0);
const fresh = [];
const reminders = [];
const quiet = [];
const current = {};
(s.manager_tier || []).forEach(function (r) {
  const k = String(r.deal_id);
  current[k] = true;
  const prev = escalated[k];
  if (!prev) {
    fresh.push(r);
    escalated[k] = { first: today, last: today, organisation: r.organisation };
    return;
  }
  const since = cal.between(Date.parse(prev.last + 'T00:00:00Z'), now);
  if (remindAfter > 0 && since >= remindAfter) {
    reminders.push(Object.assign({}, r, { first_escalated: prev.first,
      business_days_since_told: since }));
    escalated[k].last = today;
  } else {
    quiet.push(Object.assign({}, r, { first_escalated: prev.first }));
  }
});
// Anything in memory that is no longer on the manager list has been dealt with.
const resolved = Object.keys(escalated).filter(function (k) { return !current[k]; })
  .map(function (k) { return escalated[k].organisation || ('deal ' + k); });
Object.keys(escalated).forEach(function (k) { if (!current[k]) delete escalated[k]; });

// ---------------------------------------------------------------- coverage trend
const previous = runs.filter(function (r) { return r.date < today; }).slice(-1)[0] || null;
let trend = '';
if (previous) {
  const delta = s.coverage_pct - previous.coverage_pct;
  trend = 'vs ' + previous.date + ': coverage ' + previous.coverage_pct + '% -> ' +
    s.coverage_pct + '% (' + (delta >= 0 ? '+' : '') + delta + ' pts), uncovered ' +
    previous.uncovered + ' -> ' + s.uncovered_before;
}
const nextRuns = runs.filter(function (r) { return r.date !== today; })
  .concat([{ date: today, coverage_pct: s.coverage_pct, uncovered: s.uncovered_before,
    overdue: (s.owner_tier || []).length + (s.manager_tier || []).length }])
  .slice(-30);

// ---------------------------------------------------------------- persist (never in preview)
const persisted = !cfg.preview_only && !demoMemory;
if (persisted) {
  store.escalated = escalated;
  store.runs = nextRuns;
}

const lines = (s.summary_lines || []).slice();
if (trend) lines.splice(2, 0, trend);
else lines.splice(2, 0, 'first recorded run — the trend line starts tomorrow');
if (fresh.length || reminders.length || quiet.length) {
  lines.push('manager: ' + fresh.length + ' new, ' + reminders.length + ' reminder(s), ' +
    quiet.length + ' already told and still open');
}
if (resolved.length) lines.push(':white_check_mark: resolved since the manager was told: ' +
  resolved.join(', '));

return [{
  json: Object.assign({}, s, {
    trend: trend,
    previous_run: previous,
    manager_new: fresh,
    manager_reminders: reminders,
    manager_already_told: quiet,
    resolved_since_escalation: resolved,
    memory_persisted: persisted,
    memory_source: demoMemory ? 'demo fixture' : 'workflow static data',
    summary: lines.join('\n'),
    _alert_body: { text: lines.join('\n') },
    _has_escalations: fresh.length + reminders.length > 0
  })
}];

// The management escalation, kept separate from the team summary on purpose.
//
// A manager does not need the forty routine activities the guard scheduled, and does not
// need the same deal every morning. They get the manager tier only — overdue past
// MANAGER_AFTER_DAYS business days, or high-value and stalled — and only what is NEW or due
// a reminder, grouped by rep so the conversation is "Dana, these three" rather than a list.
const cfg = $('config').first().json;
const s = $json;

const list = (s.manager_new || []).map(function (r) { return Object.assign({ kind: 'new' }, r); })
  .concat((s.manager_reminders || []).map(function (r) {
    return Object.assign({ kind: 'reminder' }, r);
  }));

const byOwner = {};
list.forEach(function (r) {
  const k = r.owner || 'Unassigned';
  (byOwner[k] = byOwner[k] || []).push(r);
});

const lines = [];
lines.push('*Referral network — management escalation*');
lines.push((s.manager_new || []).length + ' new · ' + (s.manager_reminders || []).length +
  ' still open since you were told · ' + (s.manager_already_told || []).length +
  ' told recently, not repeated');
Object.keys(byOwner).sort(function (a, b) { return byOwner[b].length - byOwner[a].length; })
  .forEach(function (owner) {
    lines.push('');
    lines.push('*' + owner + '* (' + byOwner[owner].length + ')');
    byOwner[owner].slice(0, 8).forEach(function (r) {
      lines.push('• ' + (r.kind === 'reminder' ? '[again, first told ' + r.first_escalated + '] ' : '') +
        r.organisation + ' (' + r.stage + ', ' + r.value + ') — ' + r.why);
    });
    if (byOwner[owner].length > 8) lines.push('  … and ' + (byOwner[owner].length - 8) + ' more');
  });
if ((s.resolved_since_escalation || []).length) {
  lines.push('');
  lines.push('Resolved since last told: ' + s.resolved_since_escalation.join(', '));
}
lines.push('');
lines.push('Coverage: ' + s.coverage_pct_after + '% of ' + s.open_deals +
  ' open deals have a next activity' + (s.trend ? ' (' + s.trend + ')' : '') + '.');

return [{ json: Object.assign({}, s, { _escalation_body: { text: lines.join('\n') } }) }];

// One Slack DM per rep, containing only that rep's deals.
//
// The team summary says "14 activities created". A rep needs "these are the four that are
// yours, and these two are overdue". Each item is one owner: what was scheduled for them
// today (or would be, in preview), and what they are overdue on (owner tier — the manager
// has not been told yet). Built in every mode so preview shows the
// exact text; whether it is SENT is decided by the next node.
//
// Test mode never DMs a real rep: every message is redirected to the Slack id mapped for
// TEST_OWNER_ID, prefixed [TEST]. No mapping for that user = nothing is sent.
const cfg = $('config').first().json;
const s = $json;
const map = cfg.owner_slack_ids || {};

const owners = {};
function ownerOf(id, name) {
  const k = String(id === null || id === undefined ? 'none' : id);
  if (!owners[k]) owners[k] = { owner_id: id, owner: name || 'Unassigned', scheduled: [],
    overdue: [] };
  return owners[k];
}

(s.decisions || []).forEach(function (d) {
  const o = ownerOf(d.rep_id, d.rep);
  if (d.action === 'create' || d.action === 'reengage') {
    if (d.outcome && d.outcome.indexOf('FAILED') === 0) return;
    o.scheduled.push(d);
  }
});
(s.owner_tier || []).forEach(function (r) { ownerOf(r.owner_id, r.owner).overdue.push(r); });

const verb = cfg.preview_only ? 'would be scheduled' : 'scheduled';
const testTarget = cfg.test_write ? (map[String(cfg.test_owner_id)] || '') : '';

return Object.keys(owners).map(function (k) {
  const o = owners[k];
  const lines = [];
  lines.push((cfg.test_write ? '[TEST] ' : '') + 'Good morning ' +
    String(o.owner).split(' ')[0] + ' — your referral pipeline today');
  if (o.scheduled.length) {
    lines.push('');
    lines.push('*' + o.scheduled.length + ' next step(s) ' + verb + ' for you*');
    o.scheduled.slice(0, 10).forEach(function (d) {
      lines.push('• ' + d.practice + ' — ' + d.activity + ' (due ' + d.due + ')');
    });
  }
  if (o.overdue.length) {
    lines.push('');
    lines.push('*' + o.overdue.length + ' overdue — please clear or reschedule*');
    o.overdue.slice(0, 10).forEach(function (r) {
      lines.push('• ' + r.organisation + ' — overdue ' + r.overdue_business_days +
        ' business day(s), since ' + r.overdue_since + '. After ' + cfg.manager_after_days +
        ' it goes to your manager.');
    });
  }
  const real = map[String(o.owner_id)] || '';
  const sendTo = cfg.test_write ? testTarget : real;
  const nothing = !o.scheduled.length && !o.overdue.length;
  return {
    json: {
      owner: o.owner,
      owner_id: o.owner_id,
      slack_id: real,
      send_to: nothing ? '' : sendTo,
      scheduled: o.scheduled.length,
      overdue: o.overdue.length,
      text: lines.join('\n'),
      held_because: nothing ? 'nothing for this rep today'
        : !cfg.slack_dm_enabled ? 'SLACK_DMS is off or OWNER_SLACK_IDS is empty'
        : cfg.preview_only ? 'preview — DMs are only sent in test or live mode'
        : !sendTo ? (cfg.test_write ? 'test mode: TEST_OWNER_ID has no Slack id in OWNER_SLACK_IDS'
          : 'no Slack id for this rep in OWNER_SLACK_IDS') : ''
    }
  };
});
